const T0 = Date.parse('2026-10-15T12:00:00.000Z')

interface Harness {
  kv: MemoryStorage
  store: PersistentStore
  server: FakeServer
  engine: SyncEngine
  sleeps: number[]
  states: ConnectionState[]
}

let engines: SyncEngine[] = []

function makeEngine(kv: MemoryStorage, server: FakeServer, sleeps: number[]) {
  const store = new PersistentStore(kv)
  let uuid = 0
  const engine = new SyncEngine({
    fetchFn: server.fetch,
    baseUrl: 'http://server.test',
    storage: store,
    now: () => T0,
    sleep: (ms) => {
      sleeps.push(ms)
      return new Promise((resolve) => setTimeout(resolve, ms))
    },
    randomUUID: () => `${String(++uuid).padStart(8, '0')}-AAAA-4AAA-8AAA-AAAAAAAAAAAA`,
  })
  engines.push(engine)
  return { store, engine }
}

function setup(options: { identity?: string | null; server?: FakeServer; kv?: MemoryStorage } = {}): Harness {
  const kv = options.kv ?? new MemoryStorage()
  if (options.identity !== null && !options.kv) kv.setItem(KEYS.identity, options.identity ?? 'Alice')
  const server = options.server ?? new FakeServer()
  const sleeps: number[] = []
  const { store, engine } = makeEngine(kv, server, sleeps)
  const states: ConnectionState[] = []
  engine.subscribe(() => states.push(engine.getConnection()))
  return { kv, store, server, engine, sleeps, states }
}

