    expect(h.server.maxPostsInFlight).toBe(1)
    expect(h.server.messages.map((m) => m.body)).toEqual(['one', 'two', 'three', 'four'])
    expect(bodies(h).map(([, s]) => s)).toEqual(['sent', 'sent', 'sent', 'sent'])
    const methods = h.server.requests.slice(-5).map((r) => r.method)
