    expect(snap.messages.find((m) => m.id === self.id)).toMatchObject({ status: 'failed', errorCode: 'self_message', seq: null })
    // The 409 message stays failed even though the server holds a message with that id (REQ-MSG-001).
    expect(snap.messages.find((m) => m.id === conflict.id)).toMatchObject({ status: 'failed', errorCode: 'id_conflict' })
    expect(snap.messages.find((m) => m.body === 'fine')?.status).toBe('sent')
    expect(h.engine.getConnection()).toBe('online')
