describe('connection state and backoff', () => {
  it('REQ-CONN-003 backs off 1, 2, 4, 8, 8 s after consecutive failures', async () => {
    const h = setup()
    h.server.setOnline(false)
    h.engine.start()
    await tick()
    expect(h.sleeps).toEqual([1000])
    await tick(999)
    expect(h.server.requests).toHaveLength(1)
    await tick(1)
    expect(h.sleeps).toEqual([1000, 2000])
    await tick(2000)
    await tick(4000)
    await tick(8000)
    expect(h.sleeps).toEqual([1000, 2000, 4000, 8000, 8000])
    expect(h.engine.getConnection()).toBe('offline')
  })

  it('REQ-CONN-003 a connection reset of the long-poll goes offline and probes after the backoff', async () => {
    const h = setup()
    h.engine.start()
    await tick()
    expect(h.engine.getConnection()).toBe('online')
    h.server.setOnline(false)
    await tick()
    expect(h.engine.getConnection()).toBe('offline')
    h.server.setOnline(true)
    await tick(1000)
    expect(h.engine.getConnection()).toBe('online')
    expect(h.states).toEqual(['online', 'offline', 'online'])
  })

  it('REQ-CONN-003 timeouts are failures', async () => {
    const h = setup()
    h.server.intercept = (req) => abortable(never(), req.signal)
    h.engine.start()
    await tick(9_999)
    expect(h.sleeps).toEqual([])
    await tick(1)
    expect(h.sleeps).toEqual([1000])
    expect(h.engine.getConnection()).toBe('offline')
  })

  it('REQ-CONN-004 any non-5xx response, including 400 to a POST, sets online and resets failures', async () => {
    const h = setup()
    h.server.intercept = (req) => (req.method === 'GET' ? Promise.resolve(errorResponse(500, 'internal')) : null)
    h.engine.start()
    await tick()
    await tick(1000)
    expect(h.sleeps).toEqual([1000, 2000])
    h.engine.send('Alice', 'rejected by the server')
    await tick()
    expect(h.states).toContain('online')
    expect(h.sleeps).toEqual([1000, 2000, 1000])
    expect(h.store.getSnapshot().messages[0].status).toBe('failed')
  })

  it('REQ-CONN-002 on reconnect flushes all queued messages first, then syncs, without duplicates', async () => {
    const h = setup()
    h.engine.start()
    await tick()
    h.server.setOnline(false)
    await tick()
    h.engine.send('Bob', 'q1')
    h.engine.send('Bob', 'q2')
    await tick()
    h.server.deliver({ from: 'Bob', to: 'Alice', body: 'while you were away' })
    h.server.setOnline(true)
    const before = h.server.requests.length
    h.engine.wake()
    await tick()
    const methods = h.server.requests.slice(before).map((r) => [r.method, r.wait])
    expect(methods.slice(0, 3)).toEqual([
      ['POST', undefined],
      ['POST', undefined],
      ['GET', 0],
    ])
    expect(h.store.getSnapshot().messages).toHaveLength(3)
    expect(bodies(h)).toEqual([
      ['q1', 'sent'],
      ['q2', 'sent'],
      ['while you were away', 'received'],
    ])
    expect(h.store.getSnapshot().outbox).toEqual([])
  })
})

describe('wake', () => {
  it('REQ-CONN-005 wake during a backoff sleep starts a new cycle immediately without resetting failures', async () => {
    const h = setup()
    h.server.setOnline(false)
    h.engine.start()
    await tick()
    expect(h.sleeps).toEqual([1000])
    h.engine.wake()
    await tick()
    expect(h.server.requests).toHaveLength(2)
    expect(h.sleeps).toEqual([1000, 2000])
    expect(h.server.requests[1]).toMatchObject({ method: 'GET', wait: 0 })
  })

  it('REQ-CONN-005 wake during a long-poll aborts it and restarts immediately, even if it never settles', async () => {
    const h = setup()
    let late: (r: HttpResponseLike) => void = () => {}
    let polls = 0
    h.server.intercept = (req) => {
      if (req.method !== 'GET' || req.wait !== 25) return null
      polls++
      // The first long-poll ignores its abort signal; a response may arrive late.
      return polls === 1 ? new Promise((resolve) => (late = resolve)) : never()
    }
    h.engine.start()
    await tick()
    const firstPoll = h.server.gets[1]
    h.engine.wake()
    await tick()
    expect(firstPoll.signal.aborted).toBe(true)
    expect(h.server.gets).toHaveLength(3)
    expect(h.server.gets[2]).toMatchObject({ wait: 25, after: 0 })
    expect(h.engine.getConnection()).toBe('online')
    expect(h.sleeps).toEqual([])
    // A response that arrives after the abort is discarded.
    late(
      jsonResponse(200, {
        messages: [{ id: '11111111-1111-4111-8111-111111111111', seq: 1, kind: 'text', from: 'Bob', to: 'Alice', body: 'late', createdAt: '2026-10-15T12:00:00.000Z', receivedAt: '2026-10-15T12:00:00.000Z' }],
        cursor: 1,
        hasMore: false,
      }),
    )
    await tick()
    expect(h.store.getSnapshot().messages).toEqual([])
    expect(h.store.getSnapshot().cursor).toBe(0)
  })

  it('REQ-SEND-004 a send wakes the engine: the POST goes out without waiting for the long-poll', async () => {
    const h = setup()
    h.engine.start()
    await tick()
    expect(h.server.pendingPolls).toBe(1)
    h.engine.send('Bob', 'now')
    // Sending itself performs no network I/O.
    expect(h.server.posts).toHaveLength(0)
    await tick()
    expect(h.server.posts).toHaveLength(1)
    expect(bodies(h)).toEqual([['now', 'sent']])
  })

  it('REQ-SEND-004 a send while offline is persisted as queued and wakes the backoff', async () => {
    const h = setup()
    h.server.setOnline(false)
    h.engine.start()
    await tick()
    const m = h.engine.send('Bob', 'offline msg')
    expect(h.kv.getItem(KEYS.outbox)).toBe(JSON.stringify([m.id]))
    await tick()
    expect(h.server.posts).toHaveLength(1)
    expect(bodies(h)).toEqual([['offline msg', 'queued']])
  })

  it('REQ-SEND-002 engine sends use a lowercase uuid, the open peer and a strictly increasing createdAt', async () => {
    const h = setup()
    h.server.setOnline(false)
    h.engine.start()
    const a = h.engine.send('Bob', 'a')
    const b = h.engine.send('Bob', 'b')
    expect(a.id).toBe('00000001-aaaa-4aaa-8aaa-aaaaaaaaaaaa')
    expect(a).toMatchObject({ from: 'Alice', to: 'Bob', kind: 'text', status: 'queued', createdAt: '2026-10-15T12:00:00.000Z' })
    expect(b.createdAt).toBe('2026-10-15T12:00:00.001Z')
    await tick()
  })
})
